-- CASAALTA V3 - Supabase schema + initial import
-- Execute this entire file in Supabase SQL Editor.

create extension if not exists pgcrypto;


create table if not exists public.empreendimentos (
  id uuid primary key default gen_random_uuid(),
  nome text not null unique,
  cidade text,
  endereco text,
  construtora text,
  status text not null default 'Ativo' check (status in ('Ativo','Inativo')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.proprietarios (
  id uuid primary key default gen_random_uuid(),
  nome text not null,
  documento text,
  telefone text,
  email text,
  observacoes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists proprietarios_nome_lower_idx on public.proprietarios ((lower(trim(nome))));

create table if not exists public.unidades (
  id uuid primary key default gen_random_uuid(),
  empreendimento_id uuid not null references public.empreendimentos(id) on delete cascade,
  codigo text not null,
  bloco text,
  andar text,
  tipologia text,
  status text not null default 'Cadastrada',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (empreendimento_id, codigo)
);

create table if not exists public.vendas (
  id uuid primary key default gen_random_uuid(),
  empreendimento_id uuid not null references public.empreendimentos(id) on delete cascade,
  unidade_id uuid not null references public.unidades(id) on delete cascade,
  proprietario_id uuid references public.proprietarios(id) on delete set null,
  data_sfh date,
  tipo_venda text not null default 'Não informado',
  status text not null default 'Ativa',
  observacoes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (unidade_id)
);

create table if not exists public.perfis (
  user_id uuid primary key references auth.users(id) on delete cascade,
  nome text,
  papel text not null default 'consulta' check (papel in ('admin','gestor','consulta')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end; $$;

drop trigger if exists trg_empreendimentos_updated on public.empreendimentos;
create trigger trg_empreendimentos_updated before update on public.empreendimentos for each row execute function public.set_updated_at();
drop trigger if exists trg_proprietarios_updated on public.proprietarios;
create trigger trg_proprietarios_updated before update on public.proprietarios for each row execute function public.set_updated_at();
drop trigger if exists trg_unidades_updated on public.unidades;
create trigger trg_unidades_updated before update on public.unidades for each row execute function public.set_updated_at();
drop trigger if exists trg_vendas_updated on public.vendas;
create trigger trg_vendas_updated before update on public.vendas for each row execute function public.set_updated_at();
drop trigger if exists trg_perfis_updated on public.perfis;
create trigger trg_perfis_updated before update on public.perfis for each row execute function public.set_updated_at();

alter table public.empreendimentos enable row level security;
alter table public.proprietarios enable row level security;
alter table public.unidades enable row level security;
alter table public.vendas enable row level security;
alter table public.perfis enable row level security;

-- All application data is private to authenticated users. Roles can be tightened later.
drop policy if exists empreendimentos_auth_all on public.empreendimentos;
create policy empreendimentos_auth_all on public.empreendimentos for all to authenticated using (true) with check (true);
drop policy if exists proprietarios_auth_all on public.proprietarios;
create policy proprietarios_auth_all on public.proprietarios for all to authenticated using (true) with check (true);
drop policy if exists unidades_auth_all on public.unidades;
create policy unidades_auth_all on public.unidades for all to authenticated using (true) with check (true);
drop policy if exists vendas_auth_all on public.vendas;
create policy vendas_auth_all on public.vendas for all to authenticated using (true) with check (true);
drop policy if exists perfis_self_read on public.perfis;
create policy perfis_self_read on public.perfis for select to authenticated using (user_id = auth.uid());

grant select, insert, update, delete on public.empreendimentos, public.proprietarios, public.unidades, public.vendas to authenticated;
grant select on public.perfis to authenticated;

