insert into public.unidades (empreendimento_id, codigo) select id, '02-11' from public.empreendimentos where nome='NEW WAVE NAÇÕES III' on conflict (empreendimento_id,codigo) do nothing;
insert into public.vendas (empreendimento_id, unidade_id, proprietario_id, data_sfh, tipo_venda) select e.id,u.id,p.id,'2017-03-09','SFH' from public.empreendimentos e join public.unidades u on u.empreendimento_id=e.id and u.codigo='02-11' left join public.proprietarios p on lower(trim(p.nome))=lower(trim('CARLA LOPES PEREIRA')) where e.nome='NEW WAVE NAÇÕES III' on conflict (unidade_id) do update set proprietario_id=excluded.proprietario_id, data_sfh=excluded.data_sfh, tipo_venda=excluded.tipo_venda, updated_at=now();
