insert into public.vendas (empreendimento_id, unidade_id, proprietario_id, data_sfh, tipo_venda) select e.id,u.id,p.id,'2016-03-04','SFH' from public.empreendimentos e join public.unidades u on u.empreendimento_id=e.id and u.codigo='01-51' left join public.proprietarios p on lower(trim(p.nome))=lower(trim('WILLIAN LUAN BONFANTI')) where e.nome='CONDOMINIO RESIDENCIAL ARBORETTO' on conflict (unidade_id) do update set proprietario_id=excluded.proprietario_id, data_sfh=excluded.data_sfh, tipo_venda=excluded.tipo_venda, updated_at=now();
insert into public.unidades (empreendimento_id, codigo) select id, '01-78' from public.empreendimentos where nome='CONDOMINIO RESIDENCIAL ARBORETTO' on conflict (empreendimento_id,codigo) do nothing;
